{"content":"import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _currenciesNotifier;
  late final AnimationController _fadeController;

  final List<CurrencyModel> _allCurrencies = [];
  int _currentPage = 0;
  bool _hasMore = true;
  bool _isLoadingMore = false;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _currenciesNotifier = ValueNotifier([]);
    _loadInitialData();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _currenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      _refreshData();
    }
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _loadInitialData() async {
    await _fetchPage(0);
  }

  Future<void> _refreshData() async {
    if (_isLoadingMore) return;
    setState(() {
      _allCurrencies.clear();
      _currentPage = 0;
    });
    _currenciesNotifier.value = [];
    await _fetchPage(0);
  }

  Future<void> _fetchPage(int page) async {
    setState(() => _isLoadingMore = true);
    try {
      final currencyRepository = context.read<CurrencyRepository>();

      final CurrencyPage result = await currencyRepository.fetchRates(
        CurrencyPageRequest(base: 'USD', page: page, pageSize: 20),
      );

      if (mounted) {
        setState(() {
          _allCurrencies.addAll(result.items);
          _currenciesNotifier.value = List<CurrencyModel>.from(_allCurrencies);
          _currentPage = result.page + 1;
          _hasMore = result.hasMore;
          _isLoadingMore = false;
        });
      }

      if (result.items.isNotEmpty) {
        currencyRepository.saveCurrencyList(result.items);
      }
    } catch (_) {
      if (mounted) setState(() => _isLoadingMore = false);
    }
  }

  void _loadMore() {
    if (_hasMore && !_isLoadingMore) {
      _fetchPage(_currentPage);
    }
  }

  void _filterCurrencies(String query) {
    final String lowerQuery = query.toLowerCase();
    final Iterable<CurrencyModel> result = _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    });

    _currenciesNotifier.value = result.toList(growable: false);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: ValueListenableBuilder<List<CurrencyModel>>(
        valueListenable: _currenciesNotifier,
        builder: (BuildContext context, List<CurrencyModel> currencies, _) {
          if (currencies.isEmpty && !_isLoadingMore) {
            return const Center(child: CircularProgressIndicator());
          }

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
